function ascvd(v){const L=Math.log,a=L(v.a),tc=L(v.tc),h=L(v.hdl),s=L(v.sbp),t=v.tx==1,d=v.dm,sm=v.sm;let sum,base,mean;
 if(v.m==0&&v.r==0){sum=-29.799*a+4.884*a*a+13.540*tc-3.114*a*tc-13.578*h+3.149*a*h+(t?2.019*s:1.957*s)+7.574*sm-1.665*a*sm+0.661*d;base=0.9665;mean=-29.18}
 else if(v.m==0){sum=17.114*a+0.940*tc-18.920*h+4.475*a*h+(t?(29.291*s-6.432*a*s):(27.820*s-6.087*a*s))+0.691*sm+0.874*d;base=0.9533;mean=86.61}
 else if(v.r==0){sum=12.344*a+11.853*tc-2.664*a*tc-7.990*h+1.769*a*h+(t?1.797*s:1.764*s)+7.837*sm-1.795*a*sm+0.658*d;base=0.9144;mean=61.18}
 else{sum=2.469*a+0.302*tc-0.307*h+(t?1.916*s:1.809*s)+0.549*sm+0.645*d;base=0.8954;mean=19.54}
 const r=100*(1-Math.pow(base,Math.exp(sum-mean)));return `10-year ASCVD risk = ${fx(r,1)}% → ${r<5?'low (<5%)':r<7.5?'borderline (5–7.4%)':r<20?'intermediate (7.5–19.9%)':'high (≥20%)'}.`}
