N('meld','MELD, MELD-Na and MELD 3.0','Gastroenterology','Kamath PS 2001; Kim WR NEJM 2008 (MELD-Na); Kim WR Gastroenterology 2021 (MELD 3.0)','Mortality in end-stage liver disease',[['Bilirubin (mg/dL)','b'],['INR','i'],['Creatinine (mg/dL)','c'],['Sodium (mmol/L)','na'],['Albumin (g/dL)','alb'],['Dialysis ≥2×/week (or CVVHD 24 h)','d',[['No',0],['Yes',1]]],['Sex','m',SEX]],v=>meldAll(v),'Lab floors: values <1 set to 1; creatinine capped at 4 (or 4 if dialysis; MELD 3.0 cap 3.0).');
function meldAll(v){const L=Math.log;let b=Math.max(v.b,1),i=Math.max(v.i,1),c=v.d==1?4:Math.min(Math.max(v.c,1),4),na=Math.min(Math.max(v.na,125),137);
 let m=10*(0.957*L(c)+0.378*L(b)+1.120*L(i)+0.643);m=Math.round(m*10)/10;m=Math.round(m);
 let mn=m>11?m+1.32*(137-na)-0.033*m*(137-na):m;mn=Math.round(mn);
 const c3=v.d==1?3:Math.min(Math.max(v.c,1),3),al=Math.min(Math.max(v.alb,1.5),3.5),f=v.m==1?0:1;
 const m3=1.33*f+4.56*L(b)+0.82*(137-na)-0.24*(137-na)*L(b)+9.09*L(i)+11.14*L(c3)+1.85*(3.5-al)-1.83*(3.5-al)*L(c3)+6;
 return `MELD = ${fx(m,0)}; MELD-Na = ${fx(mn,0)}; MELD 3.0 = ${isFinite(m3)?Math.round(m3):'NaN'}. 3-month mortality (MELD): <10 ~2%, 10–19 ~6%, 20–29 ~20%, 30–39 ~53%, ≥40 ~71%.`}
