N('tpn','PN macronutrient calories & osmolarity','Nutrition','Standard: dextrose 3.4 kcal/g, amino acid 4 kcal/g, lipid 20% 2 kcal/mL (10 kcal/g); osmolarity estimate (dextrose 5, AA 10 mOsm/g)','Parenteral nutrition',[['Dextrose (g/day)','d'],['Amino acids (g/day)','a'],['Lipid 20% (mL/day)','l'],['Total volume (mL/day)','v'],['Weight (kg)','w']],v=>{const z=x=>isFinite(x)?x:0;const k=z(v.d)*3.4+z(v.a)*4+z(v.l)*2;const os=(z(v.d)*5+z(v.a)*10)/(v.v/1000);return `Total ≈ ${fx(k,0)} kcal/day${isFinite(v.w)?` (${(k/v.w).toFixed(1)} kcal/kg)`:''}; GIR ${isFinite(v.w)?fx(z(v.d)*1000/(v.w*1440),1):'–'} mg/kg/min; est. osmolarity ≈ ${fx(os,0)} mOsm/L (${os>900?'>900: central line required':'≤900: peripheral possible'}).`});
