N('fluids','IV fluid composition','Fluids','Manufacturer data / Myburgh JA, Mythen MG. NEJM 2013','Compare crystalloids',[['Fluid','i',FL.map((f,i)=>[f[0],i])]],v=>{const f=FL[v.i];return `${f[0]}: Na ${f[1]}, Cl ${f[2]}, K ${f[3]}, Ca ${f[4]}, buffer ${f[5]} mmol/L; osmolarity ~${f[6]} mOsm/L. ${f[7]}`});
N('crcl_dose','Renal dose band helper','Dosing','KDIGO / product labeling conventions','Classify CrCl band',[['CrCl (mL/min)','c']],v=>`CrCl ${v.c} → ${v.c>=90?'normal':v.c>=60?'mild ↓ (60–89)':v.c>=30?'moderate (30–59)':v.c>=15?'severe (15–29)':'<15 / dialysis'} — check each drug’s labeling for adjustment.`);
N('propofol_kcal','Propofol lipid calories','Nutrition','Propofol 1% = 1.1 kcal/mL','Non-nutritional calories',[['Rate (mL/h)','r']],v=>`${fx(v.r*24,0)} mL/day ≈ ${fx(v.r*24*1.1,0)} kcal/day from lipid — subtract from PN/EN target; monitor triglycerides.`);
N('o2_cyl','Oxygen cylinder duration','Respiratory','Standard: duration = (PSI − 200) × factor / flow','Portable O2 time',[['Pressure (psi)','p'],['Cylinder','f',[['D (0.16)',0.16],['E (0.28)',0.28],['M (1.56)',1.56],['H/K (3.14)',3.14]]],['Flow (L/min)','l']],v=>`≈ ${fx((v.p-200)*v.f/v.l,0)} minutes remaining (200 psi safety reserve).`);
N('pao2_est','Expected PaO2 for age (room air)','Respiratory','Sorbini CA 1968 approximation','PaO2 ≈ 109 − 0.43 × age',[['Age','a']],v=>`Expected PaO2 ≈ ${fx(109-0.43*v.a,0)} mmHg (sea level).`);
N('etco2','PaCO2–EtCO2 gradient','Respiratory','Standard','Dead-space marker',[['PaCO2','a'],['EtCO2','e']],v=>`Gradient = ${fx(v.a-v.e,0)} mmHg (normal 2–5; ↑ with dead space: PE, low CO, high PEEP, COPD).`);
N('calc_ivc','IVC collapsibility / distensibility index','Hemodynamics','Barbier C 2004 (dIVC ventilated); Feissel 2004','Fluid responsiveness (ultrasound)',[['IVC max diameter (cm)','mx'],['IVC min diameter (cm)','mn'],['Ventilated (passive)?','v',[['Spontaneous breathing',0],['Mechanically ventilated, passive',1]]]],v=>v.v==1?`Distensibility = ${fx(100*(v.mx-v.mn)/v.mn,0)}% (>18% suggests fluid responsiveness).`:`Collapsibility = ${fx(100*(v.mx-v.mn)/v.mx,0)}% (>40–50% suggests fluid responsiveness; poor reliability spontaneously breathing).`);
N('vti_co','LVOT VTI cardiac output (echo)','Hemodynamics','Standard Doppler echocardiography','SV = VTI × LVOT area',[['LVOT diameter (cm)','d'],['LVOT VTI (cm)','vti'],['Heart rate','hr']],v=>{const sv=Math.PI*Math.pow(v.d/2,2)*v.vti;return `SV = ${fx(sv,0)} mL; CO = ${fx(sv*v.hr/1000,2)} L/min. (VTI <18 cm suggests low SV; ΔVTI ≥10–15% after PLR = fluid responsive.)`});
N('plr','Passive leg raise / fluid challenge response','Hemodynamics','Monnet X et al. Intensive Care Med 2016','Percent change',[['Baseline (SV, VTI or CO)','a'],['After PLR/fluid','b']],v=>{const c=100*(v.b-v.a)/v.a;return `Change = ${fx(c,1)}% → ${c>=10?'≥10%: FLUID RESPONSIVE (PLR); ≥15% for fluid bolus':'<10%: not fluid responsive'}.`});
N('svv','Stroke volume variation','Hemodynamics','Marik PE et al. Crit Care Med 2009','SVV = (SVmax − SVmin)/SVmean',[['SV max','mx'],['SV min','mn']],v=>{const s=100*(v.mx-v.mn)/((v.mx+v.mn)/2);return `SVV = ${fx(s,1)}% (>12–13% suggests fluid responsiveness in passive, VT ≥8 mL/kg, sinus rhythm).`});
N('cvp_map','Mean perfusion pressure (MPP)','Hemodynamics','Ostermann M 2018','MPP = MAP − CVP',[['MAP','m'],['CVP','c']],v=>`MPP = ${fx(v.m-v.c,0)} mmHg (<60 associated with AKI progression).`);
N('ppep','Abdominal compartment (WSACS) grading','Neuro/IAH','Kirkpatrick AW et al. Intensive Care Med 2013 (WSACS)','IAP grade',[['IAP (mmHg)','p'],['MAP (optional)','m']],v=>{const g=v.p<12?'Normal (<12)':v.p<=15?'IAH grade I (12–15)':v.p<=20?'IAH grade II (16–20)':v.p<=25?'IAH grade III (21–25)':'IAH grade IV (>25)';return g+(isFinite(v.m)?`; APP = ${(v.m-v.p).toFixed(0)} (target ≥60).`:'.')+' ACS = sustained IAP >20 with new organ dysfunction.'});
N('ptt_hours','Time between dates/hours (bundle timing)','Conversions','—','Elapsed time helper',[['Start hour (0–24, decimal)','a'],['End hour','b']],v=>{let d=v.b-v.a;if(d<0)d+=24;return `Elapsed ${fx(d,2)} h (${fx(d*60,0)} min).`});


CALCS.forEach(x=>{x.src=x.src||'book'});const _ids=new Set(CALCS.map(x=>x.id));C2.forEach(x=>{if(!_ids.has(x.id)){CALCS.push(x);_ids.add(x.id)}});
